		for i < startIdx {
			BodyLongPeriodTotal += candleRange(0, inOpen[i], inHigh[i], inLow[i], inClose[i])
			i += 1
		}
		i = ShadowVeryShortTrailingIdx
		for i < startIdx {
			ShadowVeryShortPeriodTotal += candleRange(1, inOpen[i], inHigh[i], inLow[i], inClose[i])
			i += 1
		}
